std::vector<int> A = {1, 3, 5, 7};
std::vector<int> B = {2, 3, 6, 7};
std::vector<int> C; // Output container

// Elements must be sorted!

// Merges A and B into C (1, 2, 3, 5, 6, 7)
std::set_union(
    A.begin(), A.end(),
    B.begin(), B.end(),
    std::back_inserter(C)
);

// Optional: Using custom comparator
std::set_union(
    A.begin(), A.end(),
    B.begin(), B.end(),
    std::back_inserter(C),
    std::greater<int>()
);
